insert into public.products (slug,name,collection,tagline,description,price_cents,images,styles,stones,is_nfc,needs_size,featured,active,sort,owner_to_confirm,options,personalization_prompt) values
('tap-to-connect-bracelet','ConnecQ Tap-to-Connect Bracelet','tap-to-connect','Eight stones, one NFC chip in the centerpiece.','A hand-strung stone bracelet with an NFC chip sealed into the centerpiece. Hold a phone to it and it opens the link you choose: your website, a music video, your socials or a Google review request. One link is programmed at a time. Water resistant and very flexible, sized to your wrist.',7500,array['/products/ttc-tiger-onyx-hex.webp','/products/ttc-tritone-jasper.webp','/products/ttc-onyx-worn.webp']::text[],'[{"key":"tigers-eye-onyx","name":"Tiger eye & onyx","image":"/products/ttc-tiger-onyx-hex.webp","price_cents":8500},{"key":"mixed-tiger-eye","name":"Mixed color tiger eye","image":"/products/ttc-tritone-jasper.webp","price_cents":8500},{"key":"blue-gold-tiger-eye","name":"Blue & gold tiger eye","price_cents":8500},{"key":"brown-tiger-eye","name":"Brown tiger eye","price_cents":8500},{"key":"black-obsidian","name":"Black obsidian","image":"/products/ttc-onyx-worn.webp","price_cents":8000},{"key":"black-lava-rock","name":"Black lava rock","price_cents":8000},{"key":"leopard-jasper","name":"Leopard jasper","price_cents":7500},{"key":"snowflake-jasper","name":"Snowflake jasper","price_cents":7500}]'::jsonb,array['Tiger eye','Onyx','Obsidian','Lava rock','Jasper']::text[],true,true,true,true,10,'Stone prices are from the Etsy listing. Photos needed for blue & gold tiger eye, brown tiger eye, lava rock, leopard and snowflake jasper. Is the polished black one in the worn photo obsidian?','[]'::jsonb,null),
('custom-logo-tap-to-connect','ConnecQ Custom Bracelet with Your Logo','custom','Your logo, photo or letters on the charm, your link in the chip.','The Tap-to-Connect bracelet with your logo, a photo, your Greek letters, a QR code, your pet or a solid color sealed into the charm. The NFC chip opens the link you choose with one tap. Amy and Aaron confirm the design with you before it is made.',9999,array['/products/logo-charm-pk.webp','/products/logo-charm-agate.webp','/products/logo-charm-worn.webp']::text[],'[]'::jsonb,array['Tiger eye','Onyx','Agate','Hematite']::text[],true,true,true,true,20,null,'[{"label":"Customization","values":["Logo","Photo","Fraternity","Sorority","QR Code","Pic of Pet","Solid Color","N/A"]}]'::jsonb,'Tell us the stones or colors you want and the link for your NFC chip. Email your logo or photo to Anderberrybracelets@gmail.com after you order.'),
('executive-3-piece-set','ConnecQ Executive 3-Piece Set','custom','Custom bracelet, lapel pin and keychain, all with NFC.','A matching custom bracelet, lapel pin and keychain carrying your logo, each with an NFC chip that shares your link with one tap. Boxed and ready to give: made for executives, staff gifts and brand launches.',24997,array['/products/gift-set-rnb.webp','/products/gift-set-legalshield.webp']::text[],'[]'::jsonb,array['Onyx','Red jasper','Amethyst']::text[],true,true,true,true,30,'Price $249.97 from an Etsy search snippet. Confirm. Confirm permission to show the R&B Versus Live and LegalShield logos.','[{"label":"Customization","values":["Logo","Photo","Fraternity","Sorority","QR Code","Pic of Pet","Solid Color","N/A"]}]'::jsonb,'Tell us the stones or colors you want and the link for your NFC chip. Email your logo or photo to Anderberrybracelets@gmail.com after you order.'),
('executive-2-piece-set','ConnecQ Executive 2-Piece Set','custom','Custom bracelet and lapel pin, both with NFC.','A custom bracelet and a matching lapel pin with your logo, each with an NFC chip that opens your link with one tap. Wear them together for meetings, conferences and events.',16998,array['/products/lapel-pin-coat.webp','/products/logo-charm-agate.webp','/products/lapel-pin-front.webp']::text[],'[]'::jsonb,array['Onyx','Agate','Hematite','Tiger eye']::text[],true,true,false,true,35,'Price $169.98 from an Etsy search snippet. Confirm, and send a photo of a real 2-piece set.','[{"label":"Customization","values":["Logo","Photo","Fraternity","Sorority","QR Code","Pic of Pet","Solid Color","N/A"]}]'::jsonb,'Tell us the stones or colors you want and the link for your NFC chip. Email your logo or photo to Anderberrybracelets@gmail.com after you order.'),
('nfc-keychain','ConnecQ Custom Keychain with NFC','custom','Your logo on a keychain that shares your link.','A domed logo keychain with an NFC chip sealed inside. Tap a phone to it and it opens your website, card or socials. Shown here as part of a gift set.',7999,array['/products/gift-set-rnb.webp']::text[],'[]'::jsonb,array[]::text[],true,false,false,true,40,'Price $79.99 from an Etsy search snippet. Confirm, and send a photo of the keychain on its own.','[{"label":"Customization","values":["Logo","Photo","Fraternity","Sorority","QR Code","Pic of Pet","Solid Color","N/A"]}]'::jsonb,'Tell us the stones or colors you want and the link for your NFC chip. Email your logo or photo to Anderberrybracelets@gmail.com after you order.'),
('heart-nfc-charm','ConnecQ Heart Charm with NFC','tap-to-connect','A custom heart-shaped charm with an NFC chip. Bracelet not included.','A heart-shaped charm with your photo, logo or color, and an NFC chip that opens your link with one tap. Add it to a bracelet, bag or keyring. Bracelet not included.',3999,array[]::text[],'[]'::jsonb,array[]::text[],true,false,false,true,45,'Price $39.99 from an Etsy search snippet. Photo needed.','[{"label":"Customization","values":["Logo","Photo","Fraternity","Sorority","QR Code","Pic of Pet","Solid Color","N/A"]}]'::jsonb,'Tell us the stones or colors you want and the link for your NFC chip. Email your logo or photo to Anderberrybracelets@gmail.com after you order.'),
('purple-and-gold-stack','Purple & Gold Tiger Eye Bracelet','gemstone','Purple tiger eye, honey tiger eye and gold hematite.','Purple and honey tiger eye with polished gold hematite, made for wearers who rep purple and gold. Shown with a custom charm; order it plain or ask for your chapter’s charm.',6500,array['/products/purple-gold-stack.webp']::text[],'[]'::jsonb,array['Purple tiger eye','Tiger eye','Hematite']::text[],false,true,false,true,50,'Based on the Etsy ''Omega Psi Phi Inspired'' listing ($65; an older snapshot showed $39.99). Confirm name, price, and whether Greek letters may be used.','[]'::jsonb,null),
('onyx-signet-bracelet','Onyx Signet Bracelet','gemstone','Polished onyx rounds around a square onyx signet.','Polished black onyx rounds with a square onyx centerpiece and matte hematite spacers. Hand-strung on stretch cord.',null,array['/products/onyx-square.webp','/products/onyx-tiger-in-hand.webp']::text[],'[]'::jsonb,array['Onyx','Hematite']::text[],false,true,false,true,60,'Name and price needed.','[]'::jsonb,null),
('tiger-eye-hex-bracelet','Tiger Eye Hex Bracelet','gemstone','Mixed tiger eye rounds with a cut hex centerpiece.','Golden, blue and red tiger eye rounds around a faceted tiger eye hex. Hand-strung on stretch cord.',null,array['/products/tiger-eye-hex.webp','/products/onyx-tiger-in-hand.webp']::text[],'[]'::jsonb,array['Tiger eye']::text[],false,true,false,true,65,'Name and price needed.','[]'::jsonb,null),
('eclipse-collection','The Eclipse Collection','gemstone','AnderBerry bracelets from the Eclipse Collection.','Hand-strung AnderBerry bracelets from the Eclipse Collection.',null,array[]::text[],'[]'::jsonb,array[]::text[],false,true,false,false,70,'Hidden until we have a photo, stones, description and price from the Etsy listing.','[]'::jsonb,null),
('logo-charm-bracelet','Logo Charm Bracelet','custom','Any logo, sealed in a charm, strung on the stones you pick.','For businesses, events, teams, chapters and families. Your logo is sealed under a clear dome on a round charm and strung with matte agate, onyx, hematite or tiger eye. Bulk orders welcome.',null,array['/products/logo-charm-agate.webp','/products/logo-charm-tcb.webp','/products/logo-charm-novelty.webp','/products/logo-charm-worn.webp']::text[],'[]'::jsonb,array['Agate','Onyx','Hematite','Tiger eye']::text[],false,true,false,true,75,'Price per piece and bulk pricing needed. Confirm permission to show the TCB 54 Hundred and MS Novelty logos.','[]'::jsonb,null),
('logo-lapel-pin','Logo Lapel Pin','pins','A domed logo pin with a clutch back. NFC chip optional.','Your logo under a clear dome on a pearl-finish disc with a gold clutch back. Add an NFC chip and the pin shares your contact card, socials, a document or a video with one tap.',null,array['/products/lapel-pin-coat.webp','/products/lapel-pin-front.webp','/products/lapel-pin-back.webp','/products/lapel-pin-side.webp']::text[],'[{"key":"standard","name":"Standard"},{"key":"nfc","name":"With NFC chip"}]'::jsonb,array[]::text[],true,false,false,true,80,'Price needed for standard and NFC versions.','[]'::jsonb,null),
('stylish-cigar-nub-holder','Stylish Cigar Nub Holder & Poker','pins','Stone, bone and wood beads on a steel cigar poker.','Smoke your cigar down to the nub. A steel pick stacked with carved bone, dzi-style glass, agate and wood beads, capped at the end. Each one is one of a kind.',3999,array['/products/hat-pin-dzi.webp','/products/hat-pin-agate.webp','/products/hat-pin-crackle.webp','/products/hat-pin-display.webp']::text[],'[{"key":"dzi","name":"Dzi eye","image":"/products/hat-pin-dzi.webp"},{"key":"agate","name":"Fire agate","image":"/products/hat-pin-agate.webp"},{"key":"crackle","name":"Bone crackle","image":"/products/hat-pin-crackle.webp"}]'::jsonb,array['Agate','Bone','Wood']::text[],false,false,false,true,85,'Price $39.99 from an Etsy search snippet. Confirm these photos are the Stylish Cigar Nub Holder (they were listed as beaded pins before).','[]'::jsonb,null),
('skull-cigar-nub-holder','Skull Head Cigar Nub Holder & Poker','pins','A skull-topped steel cigar poker.','A steel cigar nub holder and poker finished with a skull head. Holds your cigar to the last draw.',3499,array[]::text[],'[]'::jsonb,array[]::text[],false,false,false,true,90,'Price $34.99 from an Etsy search snippet. Photo needed.','[]'::jsonb,null)
